BOOK_TITLE='La coerenza davanti al limite'
BOOK_EXCERPT='Un eBook CurioMondo su identità, dignità, cura e sul significato di restare fedeli ai propri valori quando il controllo diminuisce.'

mp=Path('curiomondo-site-manifest.json')
