if NUMBER in used: raise SystemExit(f'Numero {NUMBER} già usato')

page=f'''<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>{html.escape(QUESTION)} | CurioMondo</title><meta name="description" content="Domanda del giorno del 12 settembre 2026: {html.escape(EXCERPT)}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="https://curiomondo.it{Q_URL}"><link rel="icon" href="/favicon.ico"><link rel="stylesheet" href="/assets/css/site-base-v210.css"><link rel="stylesheet" href="/assets/css/biblioteca-v1.css?v=308"><link rel="stylesheet" href="/assets/css/daily-question-v273.css"><link rel="stylesheet" href="/assets/css/global-header-v275.css"><script defer src="/assets/js/global-header-v275.js"></script></head><body class="cm-daily-page"><header class="cm-global-header" data-cm-global-header="v275"><nav class="cm-global-header__inner" aria-label="Navigazione della pagina"><a class="cm-global-header__back" href="/" aria-label="Torna alla home di CurioMondo"><span class="cm-global-header__back-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M19 12H5"></path><path d="m11 18-6-6 6-6"></path></svg></span></a><a class="cm-global-header__brand" href="/" aria-label="CurioMondo, home"><span aria-hidden="true">Curio<span>Mondo</span></span></a><button class="cm-global-header__theme" data-cm-global-theme type="button" aria-label="Attiva modalità scura" aria-pressed="false"><span aria-hidden="true">☾</span></button></nav></header><main class="cm-q-page"><section class="cm-q-hero" aria-labelledby="question-title"><div class="cm-q-topline"><span class="cm-q-badge">Domanda del giorno</span><time class="cm-q-date" datetime="{TODAY}">{DATE_LABEL}</time></div><p class="cm-q-eyebrow">Uno spazio per fermarsi e pensare.</p><h1 id="question-title">{html.escape(QUESTION)}</h1><p class="cm-q-meta"><span>3 min di lettura</span><span class="cm-q-dot" aria-hidden="true"></span><span>CurioMondo</span></p></section><article class="q-flow cm-daily-flow" aria-label="Risposta alla Domanda del giorno"><p>La coerenza sembra una qualità che appartiene alla vita: scegliere, mantenere promesse, correggersi, decidere che cosa conta. Davanti alla morte, però, il margine di scelta può restringersi. Malattia, incidente, età o circostanze possono toglierci proprio quel controllo con cui abbiamo costruito l’immagine di noi stessi.</p><p>Per questo un modo di morire coerente non può significare una scena perfettamente corrispondente al nostro carattere. Nessuno controlla tutte le condizioni della propria fine. La coerenza, se esiste, riguarda piuttosto ciò che abbiamo preparato prima: le relazioni che abbiamo coltivato, i valori dichiarati con chiarezza, le decisioni affidate a persone di fiducia.</p><p>Una persona indipendente può aver bisogno di essere assistita. Una persona coraggiosa può avere paura. Chi ha sempre protetto gli altri può trovarsi nella posizione di ricevere aiuto. Queste contraddizioni apparenti non cancellano una vita. Possono mostrare che l’identità non è una posa da mantenere fino all’ultimo, ma un insieme di valori capace di attraversare anche la vulnerabilità.</p><p>Esiste poi una differenza tra dignità e controllo. La dignità non dipende dall’autosufficienza assoluta né dalla capacità di scegliere ogni dettaglio. Può sopravvivere nel modo in cui siamo trattati, ascoltati e accompagnati, e nel rispetto delle preferenze che abbiamo espresso quando eravamo in grado di farlo.</p><p>La domanda sulla morte diventa quindi una domanda sul presente. Se desideriamo che le persone vicine sappiano che cosa conta per noi, dobbiamo dirlo mentre possiamo farlo. Se alcune relazioni meritano una riparazione, non esiste garanzia che avremo un momento finale perfetto per sistemarle.</p><p>Essere coerenti non significa nemmeno rifiutare di cambiare idea. Una scelta fatta anni prima può essere rivista quando la realtà modifica ciò che comprendiamo di noi stessi. La fedeltà più profonda può consistere proprio nel non trasformare un vecchio principio in una prigione.</p><p class="q-pull cm-daily-question">Se non potessi scegliere come finirà la tua vita, quali valori vorresti che fossero comunque riconoscibili nel modo in cui hai vissuto?</p><p>Oggi la domanda resta nel presente: la coerenza della fine, per quanto possiamo influenzarla, comincia dalle decisioni e dalle relazioni che stiamo costruendo adesso.</p><a class="cm-daily-book-link" href="{BOOK_URL}"><span><small>Continua la riflessione</small><strong>Leggi l’eBook collegato</strong></span><span class="cm-daily-book-arrow" aria-hidden="true">→</span></a></article></main><footer class="cm-q-footer" aria-label="Collegamenti informativi"><a href="/pagine/privacy.html">Privacy</a><a href="/pagine/chi-siamo.html">Chi siamo</a></footer><script src="/assets/js/site-common-v210.js" defer></script></body></html>'''
qp=Path('domanda-del-giorno')/SLUG/'index.html'; qp.parent.mkdir(parents=True,exist_ok=True); qp.write_text(page,encoding='utf-8')

sections=[
('Coerenza non significa controllo',['Quando pensiamo alla coerenza immaginiamo spesso una linea continua tra principi e azioni. La fine della vita mette alla prova questa idea perché introduce variabili che nessuno governa completamente. Il corpo può indebolirsi, le possibilità restringersi e le decisioni dipendere anche da altre persone.','La coerenza non consiste quindi nel dirigere ogni dettaglio dell’ultimo tratto. Può essere più realistico chiedersi se le decisioni prese nel tempo hanno reso comprensibili i nostri valori a chi ci accompagnerà. Una vita coerente lascia tracce leggibili, non un copione perfetto.','Anche l’imprevisto conta. Morire in modo diverso da come avevamo immaginato non rende incoerente ciò che abbiamo vissuto. Il significato di una vita non viene riscritto automaticamente dalle circostanze dell’ultima giornata.']),
('Dignità e vulnerabilità',['Molte persone associano la dignità all’autonomia. Essere indipendenti è importante, ma non è l’unica forma possibile di dignità. Ricevere aiuto non cancella la persona che eravamo quando potevamo fare tutto da soli.','La vulnerabilità può entrare in conflitto con l’immagine che abbiamo costruito di noi stessi. Chi è stato forte può temere di essere ricordato nella fragilità. Ma una biografia non si riduce all’ultima condizione del corpo: comprende le relazioni, le scelte e gli effetti lasciati sugli altri.','Proteggere la dignità significa allora anche garantire rispetto, ascolto e proporzione nelle decisioni. Non richiede di fingere che la dipendenza non esista. Richiede di non confondere il bisogno di assistenza con la perdita di valore personale.']),
('Dire prima ciò che conta',['Molte questioni importanti diventano difficili proprio perché tendiamo a rinviarle. Preferenze sulla cura, persone di fiducia, desideri riguardo alla presenza dei familiari e questioni pratiche restano spesso implicite finché una crisi riduce lo spazio per parlarne.','La preparazione non elimina l’incertezza, ma può diminuire il peso delle decisioni lasciate agli altri. Dire che cosa conta non significa prevedere ogni scenario. Significa offrire criteri che possano orientare scelte future quando noi potremmo non riuscire a esprimerci.','Lo stesso vale per le relazioni. Nessuna conversazione garantisce una chiusura perfetta, ma alcune parole dette in tempo evitano di affidare tutto a un ipotetico ultimo momento che potrebbe non arrivare nelle condizioni immaginate.']),
('Cambiare idea senza tradirsi',['La coerenza viene spesso confusa con la rigidità. In realtà una persona può restare fedele ai propri valori modificando una decisione quando cambiano informazioni, condizioni o priorità. La capacità di correggersi è parte della responsabilità.','Una preferenza espressa anni prima può non rappresentare più ciò che desideriamo. Per questo è utile che le decisioni importanti siano verificabili e aggiornabili, invece di diventare promesse rivolte a una versione passata di noi stessi.','Cambiare idea non significa che il principio originario fosse falso. Può significare che abbiamo compreso meglio il suo scopo e trovato un modo diverso per rispettarlo nelle circostanze reali.']),
('La memoria degli altri',['Dopo una morte, la coerenza di una vita viene ricostruita anche dallo sguardo di chi resta. Ognuno conserva episodi diversi e nessuna memoria coincide perfettamente con l’immagine che una persona aveva di sé.','Questo limite può essere liberatorio. Non possiamo controllare completamente come saremo ricordati, ma possiamo influenzare la qualità delle relazioni che producono quei ricordi. Gesti ripetuti, affidabilità, cura e responsabilità pesano più di un’immagine finale costruita per essere simbolica.','La reputazione postuma non dovrebbe diventare un altro pubblico da soddisfare. Il punto è piuttosto riconoscere che vivere secondo certi valori crea conseguenze che continuano oltre il momento in cui non possiamo più raccontarci.']),
('La domanda torna alla vita',['Chiedersi come morire in modo coerente rischia di portarci troppo lontano nel futuro. La parte davvero disponibile è il presente: come trattiamo le persone, quali responsabilità assumiamo e quali scelte continuiamo a rimandare.','Non serve vivere pensando continuamente alla morte. Basta riconoscere che alcune decisioni diventano più difficili quando vengono rinviate indefinitamente. Chiarezza, documenti ordinati, conversazioni oneste e relazioni curate sono strumenti della vita prima ancora che della fine.','Forse la coerenza più realistica consiste nel non chiedere all’ultimo momento di correggere tutto ciò che abbiamo evitato per anni. Una fine non può rendere perfetta una biografia, ma una vita consapevole può lasciare meno cose affidate al caso.'])]
parts=[]
for i,(title,pars) in enumerate(sections,1):
    p=''.join(f'<p>{html.escape(x)}</p>' for x in pars)
    parts.append(f'<section class="cm-book-page{" is-active" if i==1 else ""}" data-book-page'+('' if i==1 else ' aria-hidden="true"')+f'><span class="cm-book-kicker">eBook CurioMondo · {DATE_LABEL}</span><h1>{html.escape(BOOK_TITLE)}</h1><h2>{html.escape(title)}</h2>{p}<span class="cm-book-page-number">{i} / {len(sections)}</span></section>')
book=f'''<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{BOOK_TITLE} | eBook CurioMondo</title><meta name="description" content="{BOOK_EXCERPT}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="https://curiomondo.it{BOOK_URL}"><link rel="stylesheet" href="/assets/css/biblioteca-v1.css?v=308"><link rel="stylesheet" href="/assets/css/biblioteca-book-reader-v1.css?v=273"><link rel="stylesheet" href="/assets/css/global-header-v275.css"><script defer src="/assets/js/global-header-v275.js"></script></head><body><header class="cm-global-header" data-cm-global-header="v275"><nav class="cm-global-header__inner" aria-label="Navigazione della pagina"><a class="cm-global-header__back" href="/biblioteca/vita-relazioni/domande-per-conoscersi/" aria-label="Torna alla raccolta"><span class="cm-global-header__back-icon" aria-hidden="true">←</span></a><a class="cm-global-header__brand" href="/" aria-label="CurioMondo, home"><span aria-hidden="true">Curio<span>Mondo</span></span></a></nav></header><main class="cb-shell"><article class="cm-book-shell"><div class="cm-book-stage">{''.join(parts)}</div><nav class="cm-book-controls" aria-label="Navigazione eBook"><button type="button" data-book-prev>← Indietro</button><span data-book-status>1 / {len(sections)}</span><button type="button" data-book-next>Avanti →</button></nav><a class="cm-book-related" href="{Q_URL}">Torna alla Domanda del giorno →</a></article></main><script src="/assets/js/biblioteca-book-reader-v1.js?v=273" defer></script></body></html>'''
bp=Path('biblioteca/vita-relazioni/domande-per-conoscersi')/SLUG/'index.html'; bp.parent.mkdir(parents=True,exist_ok=True); bp.write_text(book,encoding='utf-8')

homep=Path('index.html'); home=homep.read_text(encoding='utf-8')
new_card=f'''<section class="cm-qday" aria-label="Domanda del giorno"><a aria-label="Scopri la Domanda del giorno del {DATE_LABEL}" class="cm-qday-link" href="{Q_URL}"><div class="cm-qday-card"><time class="cm-qday-date" datetime="{TODAY}"><strong>12</strong><span>SET · 2026</span></time><span class="cm-qday-k">Domanda del giorno</span><span class="cm-qday-cta">Scopri <i aria-hidden="true">→</i></span></div></a></section>'''
