arch=Path('domanda-del-giorno/index.html'); s=arch.read_text(encoding='utf-8'); marker='<section class="cb-subgrid">'; card=f'<a class="cb-subcard" href="{Q_URL}"><span class="cb-kicker">{DATE_LABEL}</span><h2>{html.escape(QUESTION)}</h2><p>{html.escape(EXCERPT)}</p><b>Leggi →</b></a>'; arch.write_text(s.replace(marker,marker+card,1),encoding='utf-8')
idx=Path('biblioteca/vita-relazioni/domande-per-conoscersi/index.html'); s=idx.read_text(encoding='utf-8'); bcard=f'<a class="cb-subcard" href="{BOOK_URL}"><span class="cb-kicker">{DATE_LABEL} · eBook</span><h2>{html.escape(BOOK_TITLE)}</h2><p>{html.escape(BOOK_EXCERPT)}</p><b>Sfoglia →</b></a>'; idx.write_text(s.replace(marker,marker+bcard,1),encoding='utf-8')

sp=Path('assets/data/search-index-v210.json'); search=json.loads(sp.read_text(encoding='utf-8')); items=[x for x in search.get('items',[]) if x.get('url') not in {Q_URL,BOOK_URL}]; items.insert(0,{"title":BOOK_TITLE,"excerpt":BOOK_EXCERPT,"url":BOOK_URL,"section":"Biblioteca / Vita e relazioni / eBook"}); items.insert(0,{"title":QUESTION,"excerpt":EXCERPT,"url":Q_URL,"section":"Domanda del giorno"}); search['items']=items; search['version']=max(int(search.get('version',0)),328); sp.write_text(json.dumps(search,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')

smp=Path('sitemap.xml'); sx=smp.read_text(encoding='utf-8')
for u in ('https://curiomondo.it'+Q_URL,'https://curiomondo.it'+BOOK_URL):
    if u not in sx:
        entry=f'  <url>\n    <loc>{u}</loc>\n    <lastmod>{TODAY}</lastmod>\n  </url>\n'; sx=re.sub(r'(<urlset[^>]*>\s*)',lambda m:m.group(1)+entry,sx,count=1)
smp.write_text(sx,encoding='utf-8')

used.append(NUMBER); state['current_question_source_number']=NUMBER; state['used_question_source_numbers']=used; state['last_question_date']=TODAY; state['last_question_slug']=SLUG
manifest.setdefault('site',{})['current_site_version']=max(int(manifest.get('site',{}).get('current_site_version',0)),328); manifest['site']['site_version']=max(int(manifest['site'].get('site_version',0)),328); mp.write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')

assert QUESTION in qp.read_text(encoding='utf-8')
assert BOOK_TITLE in bp.read_text(encoding='utf-8')
assert f'datetime="{TODAY}"' in homep.read_text(encoding='utf-8')
assert json.loads(mp.read_text(encoding='utf-8'))['daily_state']['last_question_date']==TODAY
print('Domanda del giorno 12 settembre preparata.')
